# 数据文件：src/components/permissions/ComputerUseApproval/ComputerUseApproval.tsx
# slug = src_components_permissions_ComputerUseApproval_ComputerUseApproval_tsx
# 规则：一个源文件 = 一个数据文件；中文用三引号；禁止英文双引号 " 与反斜杠 \（用「」/『』代替）。
ANNOTATIONS = [
    (1, 'before', '''本文件是「电脑操作」能力的授权弹窗，结构是两块面板二选一：系统权限缺失时显示面板一（引导用户去系统设置里打开辅助功能与屏幕录制），否则显示面板二（应用白名单与附加权限）。两块面板的交互模型完全不同——面板一只负责跳转与重试、不产生任何授权；面板二产生完整的授权结果。这种「同一个入口、两种互斥形态」的写法，注释里直接叫分派器（dispatcher），读的时候先建立这个概念，后面就顺了。'''),
    (14, 'before', '''属性只有两个：请求与完成回调。所有输入细节（应用清单、请求的权限位、TCC 状态、是否需要隐藏其它应用）都挂在请求对象上，组件完全无状态地从请求派生界面——这是权限类弹窗的通用形态，因为它只出现一次、生命周期极短。'''),
    (18, 'before', '''「全部拒绝」的常量响应：授权清单空、拒绝清单也空、权限位用默认值。注意拒绝清单也是空的——这里没有逐条声明「拒绝了哪些」，因为调用方在收到空授权时就已经知道结论了。这个常量的存在让「取消」与「明确拒绝」两条路径能共用同一个返回值。'''),
    (24, 'before', '''分派依据的注释写得很清楚：请求里带系统权限状态时，说明辅助功能或屏幕录制缺失，此时应用白名单毫无意义——用户就算逐个勾选也跑不起来。所以先修系统权限、再谈应用授权。这个顺序判断是本文件唯一的全局性决策。'''),
    (38, 'before', '''分派实现只有一行三元：有系统权限状态就渲染授权面板一，并在完成时返回全部拒绝（因为此时用户根本没做授权决定）；否则渲染应用白名单面板，把回调原样透传。'''),
    (50, 'before', '''面板一的三个选项：打开辅助功能设置、打开屏幕录制设置、重试。前两个是系统设置的深链，第三个是回到应用里重新检测。注意没有「取消」选项——取消由弹窗的退出键承担，见下面的取消回调。'''),
    (58, 'before', '''选项数组按「缺什么给什么」拼装：缺辅助功能才给对应项、缺屏幕录制才给对应项，重试项恒在最后。这种按状态稀疏生成的选项，比固定三项加禁用标记更简洁，但也意味着用户看到的项数会变化——所以重试永远在最后，位置可预期。'''),
    (96, 'before', '''重试项无条件追加在末尾。它存在的意义是让用户从系统设置回来之后有个明确的回头路，而不是必须退出弹窗、重新发起一次请求。'''),
    (106, 'before', '''三个分支全部用自己的 return 结束，其中前两个只是打开系统设置就直接返回——注意它们不调用完成回调，因为打开设置并不等于作出决定，弹窗必须留在原地等用户回来重试。这个「不完成」是刻意设计的。'''),
    (110, 'before', '''深链用的是系统设置的私有 URL 协议，后面挂着具体的隐私面板标识。这类链接在不同系统版本上可能失效，所以用了不抛错的执行函数——打开失败也不该让弹窗崩掉，用户仍可手动去设置里找。'''),
    (122, 'before', '''重试分支才调用完成回调，且不传参数——调用方收到后应该重新检测系统权限，若已授予就继续原流程。这是面板一唯一会「结束」的路径。'''),
    (135, 'before', '''两项权限各自的状态文案：授予给对勾、未授予给叉号。这里用了图形常量而不是颜色，因为颜色在部分终端不可用，而对勾与叉号在任何终端都能看出区别。'''),
    (164, 'before', '''说明文案里那句「授予屏幕录制后可能需要重启」是很实在的一条提示——系统对屏幕录制权限的生效时机有额外要求，不写这句用户会以为授权没成功。这类平台特有的坑必须写进界面，写进文档没人看。'''),
    (190, 'before', '''弹窗标题直接点明「需要系统权限」，取消回调就是完成回调——退出等于放弃本次请求，返回的仍是不授权。'''),
    (203, 'before', '''三类「哨兵应用」的警告文案：能当 shell 用、能读写任意文件、能改系统设置。这句话是授权界面里最重要的信息——用户看到的只是一个应用名，但它的能力可能等于把整台机器交出去。映射表用类别做键，说明分类是中心化维护的，不在这里临时判断。'''),
    (215, 'before', '''勾选状态是一次性初始化的集合：把所有「已解析且尚未授权」的应用标识放进去，默认全选。用状态而不是派生值，说明这个组件原本设计了可交互的勾选——但产物里只见 Set 而不见增删，说明当前版本把勾选做成了只读展示，用默认全选代替了逐项勾选。这是一个值得注意的「半成品形态」：数据结构保留了扩展能力，界面先按全选走。'''),
    (222, 'before', '''取出集合后只读使用，没有对应的写入口。这与上一条判断互相印证——授权粒度目前是「全选或全不选」，逐项勾选是预留能力。'''),
    (232, 'before', '''请求的附加权限位按固定键序筛出真正被请求的那些，得到一份有序的键名数组。固定键序而不是遍历对象，是为了让「附加权限」列表的展示顺序稳定——对象键序在不同引擎上不保证。'''),
    (249, 'before', '''允许项的文案里带上了应用数量，且用了复数辅助函数。数目来自上面那个集合，所以文案与实际授权范围严格一致，不会出现「说了三个其实授了五个」。'''),
    (262, 'before', '''拒绝项的文案里嵌了加粗的退出键提示，且标签本身是一个节点而不是字符串——这一项要让用户知道「拒绝之后还能告诉模型该怎么做」，所以文案更长、信息更多。选项标签允许是节点，是这个下拉框组件的关键能力。'''),
    (282, 'before', '''响应构造分两份：拒绝时直接返回共享的常量；允许时才逐项算出授权清单、拒绝清单与权限位。注意「拒绝清单」在允许路径下并不为空——里面装的是没被勾选、或压根没安装的应用，这样调用方才能知道哪些应用需要下次再问。'''),
    (288, 'before', '''授权清单：只收「已解析且被勾选」的应用，逐条带上标识、显示名与授权时间。时间取一次当前时刻给所有条目共用，而不是逐条取，这样同一批授权的时间戳完全一致，便于后续按批次判断。'''),
    (294, 'before', '''权限位是默认值与「本次请求的键全置真」的合并。合并顺序很关键——默认值在前，请求的键在后，所以请求过的位被打开、没请求的位保持默认。'''),
    (322, 'before', '''请求自带的说明文案可有可无，有就压暗显示在最上方。这是模型给出的「为什么要控制这些应用」的解释，放在列表之前而不是之后，因为用户是在读这段话的过程中做决定的。'''),
    (336, 'before', '''没安装的应用：用空心圆点、压暗、并注明未安装。它仍然出现在列表里，是因为用户需要知道模型想用什么却用不上——这个信息对判断模型意图有帮助，直接过滤掉反而丢信息。'''),
    (343, 'before', '''正常应用的两种状态：已勾选显示实心圆点、未勾选显示空心圆点；若该应用属于哨兵类别，再在下一行加一条加粗警告。这里用两行而不是把警告拼在同一行，是为了让警告在视觉上无法被忽略。'''),
    (366, 'before', '''附加权限段：只有在真的请求了附加权限时才出现，逐条以圆点列出。键名直接用英文标识而不是翻成中文，因为它们是协议字段，翻译反而让排查变难。'''),
    (374, 'before', '''「还有几个应用会被隐藏」的提示。这是电脑操作能力的一个副作用——它工作时会把别的应用藏起来，用户有权事先知道。提示里同样用了复数辅助函数，避免出现「1 个应用」这种别扭文案。'''),
    (394, 'before', '''下拉框的两个回调：选中把选项值翻成布尔再交给响应构造，取消恒为拒绝。注意这里没有「允许部分」的路径，与上面「勾选只读、默认全选」的判断一致。'''),
    (438, 'before', '''这个辅助函数是「扁平映射当过滤用」的写法：条件成立返回单元素数组、不成立返回空数组，于是外层一次扁平映射就同时完成了筛选与取值。它比「先过滤再映射」少一次遍历，代价是可读性——单看这个函数看不出它在上游是当过滤器用的。本文件末尾四个小函数都是这种为调用点服务的形态。'''),
]
